// `roster review <repo> --observational`: fetch → parse → identify → score, then reports/<slug>/.
// Every stage is a TOOL span inside one WORKFLOW review span (DESIGN.md §"Observability (neatlogs)").
import { join, resolve } from "node:path";
import type { Command } from "../cli.ts";
import { priceSession } from "../price/index.ts";
import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
import { fetchCheckpoints } from "../ingest/fetch.ts";
import { type ParsedSession, parseCheckpoints } from "../ingest/parse.ts";
import { type Identity, identify, inferenceAccuracy } from "../identity/index.ts";
import { survival } from "../score/survival.ts";
import { reverted } from "../score/revert.ts";
import { rework } from "../score/rework.ts";
import { buildSetupRows, buildTags, repoSlug, type ReviewReport, slugDir, writeReview } from "../review/export.ts";
import type { Outcome, Review, Session } from "../types.ts";

export const DEFAULT_CACHE = ".roster/cache";
/** Mature = at least this many first-parent commits after the session's commit, and this many seconds older than HEAD. */
export const MIN_DEPTH = 5;
export const MIN_AGE_S = 6 * 3600;

const STAGES = ["fetch", "parse", "identify", "score"] as const;
type Stage = (typeof STAGES)[number];

const USAGE = `usage: roster review <repo> --observational [--out <dir>] [--cache <dir>]

  <repo>            a git URL or a local path to a repo that has Entire checkpoints
  --observational   score sessions that already exist (evidence level A). Required for now.
  --out <dir>       where to write review.json, review.md, sessions.json and outcomes.json
                    (default reports/<slug>)
  --cache <dir>     fetch cache (default ${DEFAULT_CACHE})`;

export interface ReviewArgs {
  repo: string;
  out: string | undefined;
  cache: string;
}

/** Thrown for bad arguments. The CLI prints the message and exits 2. */
export class UsageError extends Error {}

/** Parses the arguments after `review`. Throws UsageError on anything it does not accept. */
export function parseReviewArgs(args: string[]): ReviewArgs {
  let repo: string | undefined;
  let observational = false;
  let out: string | undefined;
  let cache = DEFAULT_CACHE;
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!;
    const eq = a.indexOf("=");
    const name = eq === -1 ? a : a.slice(0, eq);
    // A flag takes its value inline (--out=dir) or as the next argument (--out dir).
    const takeValue = (): string => {
      if (eq !== -1) return a.slice(eq + 1);
      const v = args[++i];
      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
      return v;
    };
    if (name === "--observational" && eq === -1) observational = true;
    else if (name === "--out") out = takeValue();
    else if (name === "--cache") cache = takeValue();
    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
    else if (repo === undefined) repo = a;
    else throw new UsageError(`unexpected argument ${a}`);
  }
  if (repo === undefined) throw new UsageError("missing <repo>");
  if (!observational) {
    throw new UsageError("only --observational is implemented; the controlled replay path is not built yet");
  }
  return { repo, out, cache };
}

const NO_DATA =
  "no Entire data found. Run `entire enable` in the source repo, push its entire/checkpoints/v1 branch, and try again.";

function git(repo: string, args: string[]): string {
  const p = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  if (p.exitCode !== 0) throw new Error(`git ${args[0]} failed: ${p.stderr.toString().trim()}`);
  return p.stdout.toString();
}

interface ScoreContext {
  repo: string;
  head: string;
  headTime: number;
}

/** One user prompt means nobody steered the session. Needs no commit age; null when the count is unknown. */
const isUnattended = (s: ParsedSession): boolean | null => (Number.isFinite(s.n_user_prompts) ? s.n_user_prompts === 1 : null);

const tooYoung = (session_id: string, unattended: boolean | null = null): Outcome => ({
  session_id,
  status: "too_young",
  survival: null,
  reverted: null,
  rework_human: null,
  rework_agent: null,
  unattended,
  tests_at_commit: null,
  difficulty: null,
  tercile: null,
});

/**
 * Scores one session from its commit. Sessions without a trailer-linked commit, and commits that are not yet
 * mature, come back too_young with null metrics. Throws when git cannot read the commit.
 */
export function scoreSession(session: ParsedSession, ctx: ScoreContext): Outcome {
  const sha = session.commit_sha;
  if (sha === null) return tooYoung(session.id, isUnattended(session));
  const depth = Number(git(ctx.repo, ["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]).trim());
  const age = ctx.headTime - Number(git(ctx.repo, ["show", "-s", "--format=%ct", sha]).trim());
  if (depth < MIN_DEPTH || age < MIN_AGE_S) return tooYoung(session.id, isUnattended(session));

  const surv = survival(ctx.repo, [sha], ctx.head);
  const rw = rework(ctx.repo, sha);
  return {
    session_id: session.id,
    status: "mature",
    survival: surv.ratio,
    reverted: reverted(ctx.repo, sha),
    rework_human: rw.human,
    rework_agent: rw.agent,
    unattended: isUnattended(session),
    tests_at_commit: null,
    difficulty: null,
    tercile: null,
  };
}

const pct = (x: number) => `${(100 * x).toFixed(1)}%`;

async function stage<T>(n: number, name: Stage, repo: string, work: () => Promise<[T, string]>): Promise<T> {
  return withSpan("TOOL", name, { repo }, async () => {
    const [value, detail] = await work();
    console.log(`[${n}/${STAGES.length}] ${name}: ${detail}`);
    return value;
  });
}

/** Runs the whole review. Resolves to the exit code; writes reports only when every stage succeeds. */
export async function runReview(args: ReviewArgs): Promise<number> {
  const label = repoSlug(args.repo);
  const outDir = resolve(args.out ?? join("reports", slugDir(label)));
  const createdAt = new Date().toISOString();
  const reviewId = `${slugDir(label)}-${createdAt.replace(/\D/g, "").slice(0, 14)}`;

  await initObs({ workflowName: "roster-review" });
  setSession(reviewId);
  console.log(`roster review ${label} (${reviewId}) → ${outDir}`);
  try {
    return await withSpan("WORKFLOW", "review", { repo: label }, async () => {
      const fetched = await stage(1, "fetch", label, async () => {
        const f = await fetchCheckpoints(args.repo, { cacheDir: resolve(args.cache) });
        return [f, `backend=${f.backend} head=${f.headSha.slice(0, 12) || "none"}`];
      });
      if (fetched.backend === "none") {
        console.error(`roster review: ${NO_DATA}`);
        return 1;
      }
      if (fetched.headSha === "") {
        console.error("roster review: the repo has checkpoints but no HEAD commit to score them against");
        return 1;
      }

      const sessions = await stage(2, "parse", label, async () => {
        const parsed = parseCheckpoints(fetched.repoPath, fetched.backend === "refs" ? "git-refs" : "branch");
        return [parsed, `${parsed.length} sessions`];
      });

      const identities: Identity[] = await stage(3, "identify", label, async () => {
        const ids = sessions.map((s) => identify(s, fetched.repoPath));
        const setups = new Set(ids.map((i) => i.setupId).filter((x): x is string => x !== null)).size;
        const acc = inferenceAccuracy(ids);
        return [ids, `${setups} setups, tag accuracy ${acc === null ? "n/a (no tagged sessions)" : pct(acc)}`];
      });

      const headTime = Number(git(fetched.repoPath, ["show", "-s", "--format=%ct", fetched.headSha]).trim());
      const ctx: ScoreContext = { repo: fetched.repoPath, head: fetched.headSha, headTime };
      const scored = await stage(4, "score", label, async () => {
        const out: Session[] = [];
        const outcomes: Outcome[] = [];
        const failed: string[] = [];
        sessions.forEach((s, i) => {
          const id = identities[i]!;
          const cost = priceSession(s.model, {
            input: s.tokens_in,
            output: s.tokens_out,
            cache_read: s.cache_read,
            cache_write: s.cache_write,
          }).usd;
          out.push({ ...stripParsed(s), setup_id: id.setupId, cost_usd: cost });
          try {
            outcomes.push(scoreSession(s, ctx));
          } catch (err) {
            failed.push(`${s.id}: ${err instanceof Error ? err.message : String(err)}`);
            outcomes.push(tooYoung(s.id, isUnattended(s)));
          }
        });
        const mature = outcomes.filter((o) => o.status === "mature").length;
        return [
          { out, outcomes, failed },
          `${mature} mature, ${outcomes.length - mature} too young${failed.length ? `, ${failed.length} failed` : ""}`,
        ];
      });

      const notes = [
        `${scored.outcomes.filter((o) => o.status === "too_young").length} sessions are too young or have no commit: a session is mature at ≥ ${MIN_DEPTH} first-parent commits and ≥ ${MIN_AGE_S / 3600} h before HEAD`,
        ...scored.failed.map((f) => `could not be scored: ${f}`),
        `${scored.out.filter((s) => s.cost_usd === null).length} sessions have no price (unknown model, or a price that depends on prompt size)`,
        `${scored.out.filter((s) => s.setup_id === null).length} sessions have no setup because their rules hash is unknown`,
      ];
      const tags = buildTags(scored.out);
      const review: Review = {
        id: reviewId,
        repo: label,
        created_at: createdAt,
        generated_at: createdAt,
        has_entire_data: true,
        setups: buildSetupRows(scored.out, scored.outcomes),
        ...(tags ? { tags } : {}),
        label: "insufficient_data",
        suspect: null,
        odds_ratio: null,
        ci95: null,
        p_value: null,
        evidence_level: "A",
      };
      const report: ReviewReport = {
        review,
        note:
          "No suspect call. The difficulty-matched Mantel–Haenszel test (DESIGN.md §\"Difficulty and review\") is not part of this command yet, so the setup numbers below are descriptive only.",
        sessions: scored.out,
        outcomes: scored.outcomes,
        notes,
      };
      const written = writeReview(outDir, report);
      console.log(`wrote ${written.join(", ")}`);
      console.log(`label ${review.label} · evidence level ${review.evidence_level}`);
      return 0;
    });
  } finally {
    await flushObs();
  }
}

/** A ParsedSession without the parse-only fields, so sessions.json holds Session rows. */
function stripParsed(s: ParsedSession): Session {
  const { usage_source: _usage, model_source: _model, ...session } = s;
  return session;
}

export const reviewCommand: Command = {
  name: "review",
  summary: "score a repo's agent sessions (--observational)",
  usage: USAGE,
  async run(args) {
    let parsed: ReviewArgs;
    try {
      parsed = parseReviewArgs(args);
    } catch (err) {
      if (!(err instanceof UsageError)) throw err;
      console.error(`roster review: ${err.message}\n\n${USAGE}`);
      return 2;
    }
    return runReview(parsed);
  },
};
// Score: survival (DESIGN.md §"Score: survival"). Share of the lines a session's commit(s) added that
// `git blame -w -M -C HEAD` still attributes to those commits.

export interface Survival {
  added: number;
  surviving: number;
  /** surviving ÷ added; 1 when nothing was added (nothing to lose). */
  ratio: number;
}

const GENERATED = [
  /(^|\/)dist\//,
  /\.min\.[^/]*$/,
  /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|Cargo\.lock|poetry\.lock|Gemfile\.lock|composer\.lock|go\.sum)$/,
];

export function isGenerated(path: string): boolean {
  return GENERATED.some((re) => re.test(path));
}

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const r = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], {
    cwd: repo,
    stdout: "pipe",
    stderr: "pipe",
    maxBuffer: 256 * 1024 * 1024,
  });
  return { ok: r.exitCode === 0, out: r.stdout.toString() };
}

/** Added (non-blank, whitespace-insensitive) line count per non-generated file for one commit. */
function addedByFile(repo: string, sha: string): Map<string, number> {
  const res = git(repo, ["show", "-w", "--ignore-blank-lines", "-U0", "--no-renames", "--format=", sha]);
  if (!res.ok) throw new Error(`git show ${sha} failed in ${repo}`);
  const counts = new Map<string, number>();
  let file: string | null = null;
  let inHunk = false;
  for (const line of res.out.split("\n")) {
    if (line.startsWith("diff --git ")) {
      file = null;
      inHunk = false;
    } else if (!inHunk && line.startsWith("+++ ")) {
      file = line === "+++ /dev/null" ? null : line.slice(6);
    } else if (line.startsWith("@@")) {
      inHunk = true;
    } else if (inHunk && file && line.startsWith("+") && line.trim().length > 1 && !isGenerated(file)) {
      counts.set(file, (counts.get(file) ?? 0) + 1);
    }
  }
  return counts;
}

// Blame cache: repo + resolved HEAD + file → line count per full commit sha.
const blameCache = new Map<string, Map<string, number>>();

function blameCounts(repo: string, head: string, file: string): Map<string, number> {
  const key = `${repo}\0${head}\0${file}`;
  const hit = blameCache.get(key);
  if (hit) return hit;
  const counts = new Map<string, number>();
  const res = git(repo, ["blame", "-w", "-M", "-C", "--line-porcelain", head, "--", file]);
  if (res.ok) {
    // Each blamed line starts with "<40-hex sha> <orig> <final> [<group size>]"; content lines start with a tab.
    for (const line of res.out.split("\n")) {
      if (/^[0-9a-f]{40} \d+ \d+/.test(line)) {
        const sha = line.slice(0, 40);
        counts.set(sha, (counts.get(sha) ?? 0) + 1);
      }
    }
  }
  blameCache.set(key, counts);
  return counts;
}

function resolve(repo: string, rev: string): string {
  const r = git(repo, ["rev-parse", "--verify", `${rev}^{commit}`]);
  if (!r.ok) throw new Error(`cannot resolve ${rev} in ${repo}`);
  return r.out.trim();
}

export function survival(repoPath: string, commitShas: string[], headSha: string): Survival {
  const head = resolve(repoPath, headSha);
  const shas = new Set(commitShas.map((s) => resolve(repoPath, s)));

  const added = new Map<string, number>();
  for (const sha of shas) {
    for (const [file, n] of addedByFile(repoPath, sha)) added.set(file, (added.get(file) ?? 0) + n);
  }

  let total = 0;
  let surviving = 0;
  for (const [file, n] of added) {
    total += n;
    const blamed = blameCounts(repoPath, head, file);
    let mine = 0;
    for (const sha of shas) mine += blamed.get(sha) ?? 0;
    surviving += Math.min(mine, n);
  }
  return { added: total, surviving, ratio: total === 0 ? 1 : surviving / total };
}
// DESIGN.md §"Score: reverted, rework". A change counts as reverted when a later commit says
// `This reverts commit <sha>`, or when at least half of its added lines are deleted within the window.

import { DEFAULT_WINDOW, trackLines } from "./rework.ts";

export const REVERT_SHARE = 0.5;

export function reverted(repo: string, sha: string, window: number = DEFAULT_WINDOW): boolean {
  const t = trackLines(repo, sha, window);
  if (t.explicitRevert) return true;
  return t.added > 0 && t.matchedHuman + t.matchedAgent >= REVERT_SHARE * t.added;
}
// Tracks which lines a session's commit added and which later commits removed or replaced.
// DESIGN.md §"Score: reverted, rework". History is read along first parents only: a merge is
// diffed against its first parent, and the window walks first-parent commits after the landing.

export const DEFAULT_WINDOW = 20;
export const EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";
const CHECKPOINT_TRAILER = /^Entire-Checkpoint:\s*\S+/m;

/** A line is identified by its path and text. */
type LineKey = [path: string, text: string];

export interface Tracked {
  /** Lines the commit added, against its first parent. */
  added: number;
  /** Added lines that a later commit in the window removed or replaced, by commits without a checkpoint trailer. */
  matchedHuman: number;
  /** The same, by commits with an Entire-Checkpoint trailer. */
  matchedAgent: number;
  /** Some later first-parent commit says `This reverts commit <sha>`. Not limited to the window. */
  explicitRevert: boolean;
}

interface Commit {
  sha: string;
  parent: string;
  body: string;
}

function git(repo: string, args: string[]): string {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  if (p.exitCode !== 0) throw new Error(`git ${args.join(" ")} failed: ${p.stderr.toString().trim()}`);
  return p.stdout.toString();
}

function fullSha(repo: string, ref: string): string {
  return git(repo, ["rev-parse", "--verify", `${ref}^{commit}`]).trim();
}

/**
 * Commits after `sha` on the first-parent chain of HEAD, oldest first. Only descendants of `sha`
 * qualify, so a merge whose second parent carries `sha` is included. `--ancestry-path` is not
 * combined with `--first-parent`: that would drop the second-parent edge and miss the merge.
 */
function laterCommits(repo: string, sha: string): Commit[] {
  const descendants = new Set(git(repo, ["rev-list", "--ancestry-path", `${sha}..HEAD`]).split("\n"));
  const out = git(repo, ["log", "--first-parent", "--topo-order", "--reverse", "--format=%H %P%x1f%B%x1e", `${sha}..HEAD`]);
  return out
    .split("\x1e")
    .filter((rec) => rec.trim() !== "")
    .map((rec) => {
      const [head = "", body = ""] = rec.split("\x1f");
      const [commit = "", ...parents] = head.trim().split(" ");
      return { sha: commit, parent: parents[0] ?? EMPTY_TREE, body };
    })
    .filter((c) => descendants.has(c.sha));
}

function parentOf(repo: string, sha: string): string {
  const parents = git(repo, ["log", "-1", "--format=%P", sha]).trim().split(" ");
  return parents[0] || EMPTY_TREE;
}

/** Added and removed lines between two trees, read from hunk headers so that content like `--- x` is not mistaken for a header. */
function diffLines(repo: string, from: string, to: string): { added: LineKey[]; removed: LineKey[] } {
  const out = git(repo, ["diff", "-U0", "--no-color", "--no-ext-diff", "--no-renames", "--no-prefix", from, to]);
  const added: LineKey[] = [];
  const removed: LineKey[] = [];
  let oldPath = "";
  let path = "";
  let oldLeft = 0;
  let newLeft = 0;
  for (const line of out.split("\n")) {
    if (oldLeft > 0 && line.startsWith("-")) {
      removed.push([path, line.slice(1)]);
      oldLeft--;
    } else if (newLeft > 0 && line.startsWith("+")) {
      added.push([path, line.slice(1)]);
      newLeft--;
    } else if (line.startsWith("--- ")) {
      oldPath = line.slice(4).replace(/\t$/, "");
    } else if (line.startsWith("+++ ")) {
      const newPath = line.slice(4).replace(/\t$/, "");
      path = newPath === "/dev/null" ? oldPath : newPath;
    } else if (line.startsWith("@@ ")) {
      const m = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
      if (!m) throw new Error(`unparsable diff hunk: ${line}`);
      oldLeft = m[1] === undefined ? 1 : Number(m[1]);
      newLeft = m[2] === undefined ? 1 : Number(m[2]);
    }
  }
  return { added, removed };
}

function bump(counts: Map<string, number>, key: string) {
  counts.set(key, (counts.get(key) ?? 0) + 1);
}

/**
 * Follows the lines `sha` added through the next `window` first-parent commits. A removed or
 * replaced line counts once, for the first later commit that removes it. Lines are matched by
 * path and text as multisets, so a line that is re-added later is not counted as surviving.
 */
export function trackLines(repo: string, sha: string, window: number = DEFAULT_WINDOW): Tracked {
  const full = fullSha(repo, sha);
  const { added } = diffLines(repo, parentOf(repo, full), full);
  const later = laterCommits(repo, full);
  const alive = new Map<string, number>();
  for (const [path, text] of added) bump(alive, `${path}\0${text}`);

  const result: Tracked = {
    added: added.length,
    matchedHuman: 0,
    matchedAgent: 0,
    explicitRevert: later.some((c) => c.body.includes(`This reverts commit ${full}`)),
  };
  if (added.length === 0) return result;

  for (const c of later.slice(0, window)) {
    const agent = CHECKPOINT_TRAILER.test(c.body);
    for (const [path, text] of diffLines(repo, c.parent, c.sha).removed) {
      const key = `${path}\0${text}`;
      const n = alive.get(key) ?? 0;
      if (n === 0) continue;
      alive.set(key, n - 1);
      if (agent) result.matchedAgent++;
      else result.matchedHuman++;
    }
  }
  return result;
}

export interface ReworkShares {
  /** Share of the commit's added lines that later commits without a checkpoint trailer modified. */
  human: number;
  /** Share of the commit's added lines that later commits with a checkpoint trailer modified. */
  agent: number;
}

/** Shares of `sha`'s added lines that later first-parent commits in the window modified, split by author kind. */
export function rework(repo: string, sha: string, window: number = DEFAULT_WINDOW): ReworkShares {
  const t = trackLines(repo, sha, window);
  if (t.added === 0) return { human: 0, agent: 0 };
  return { human: t.matchedHuman / t.added, agent: t.matchedAgent / t.added };
}
// Per-session difficulty (DESIGN.md §"Difficulty and review"): the mean z-score, over the sessions
// being compared, of log(1 + lines changed), files touched, graph impact size and first-prompt
// length. Terciles split the sessions by that score so setups are compared like for like.

import type { Session, Tercile } from "../types.ts";
import { impactSize, type GraphOptions, type ImpactMethod } from "./graph.ts";

export type { ImpactMethod } from "./graph.ts";

export interface DifficultyFeatures {
  /** Added + deleted lines in the session's commit; null when the session has no commit. */
  lines_changed: number | null;
  files_touched: number;
  impact: number;
  /** Which impact method produced `impact`. */
  impact_method: ImpactMethod;
  first_prompt_len: number;
}

export interface DifficultyScore {
  session_id: string;
  features: DifficultyFeatures;
  difficulty: number;
  tercile: Tercile;
}

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  return { ok: p.exitCode === 0, out: p.stdout.toString() };
}

/** Lines and files changed by `sha` (binary files count as one file, zero lines). */
export function commitChange(repo: string, sha: string): { lines: number; files: string[] } | null {
  const r = git(repo, ["show", "--numstat", "--format=", "--no-renames", sha]);
  if (!r.ok) return null;
  let lines = 0;
  const files: string[] = [];
  for (const row of r.out.split("\n")) {
    const [add, del, path] = row.split("\t");
    if (path === undefined) continue;
    files.push(path);
    lines += (Number(add) || 0) + (Number(del) || 0);
  }
  return { lines, files };
}

/** Raw difficulty features of one session. */
export function features(session: Session, repo: string, opts: GraphOptions = {}): DifficultyFeatures {
  const change = session.commit_sha ? commitChange(repo, session.commit_sha) : null;
  const files = session.files.length > 0 ? session.files : change?.files ?? [];
  const impact = impactSize(repo, change ? session.commit_sha : null, files, opts);
  return {
    lines_changed: change?.lines ?? null,
    files_touched: files.length,
    impact: impact.size,
    impact_method: impact.method,
    first_prompt_len: session.first_prompt.length,
  };
}

/** z-scores of `xs`; missing values and zero-variance columns score 0 (the mean). */
export function zScores(xs: (number | null)[]): number[] {
  const present = xs.filter((x): x is number => x !== null);
  if (present.length === 0) return xs.map(() => 0);
  const mean = present.reduce((s, x) => s + x, 0) / present.length;
  const sd = Math.sqrt(present.reduce((s, x) => s + (x - mean) ** 2, 0) / present.length);
  return xs.map((x) => (x === null || sd === 0 ? 0 : (x - mean) / sd));
}

/** Mean z-score of the four features, per row, relative to all rows given. */
export function difficultyFromFeatures(rows: DifficultyFeatures[]): number[] {
  const cols = [
    zScores(rows.map((f) => (f.lines_changed === null ? null : Math.log1p(f.lines_changed)))),
    zScores(rows.map((f) => f.files_touched)),
    zScores(rows.map((f) => f.impact)),
    zScores(rows.map((f) => f.first_prompt_len)),
  ];
  return rows.map((_, i) => cols.reduce((s, c) => s + c[i]!, 0) / cols.length);
}

/**
 * Terciles by rank: the lowest third of scores is 1, the highest third 3. Ties break by id so the
 * split is deterministic.
 */
export function terciles<T extends { session_id: string; difficulty: number }>(rows: T[]): Map<string, Tercile> {
  const sorted = [...rows].sort(
    (a, b) => a.difficulty - b.difficulty || (a.session_id < b.session_id ? -1 : a.session_id > b.session_id ? 1 : 0),
  );
  const out = new Map<string, Tercile>();
  sorted.forEach((r, i) => out.set(r.session_id, (Math.floor((3 * i) / sorted.length) + 1) as Tercile));
  return out;
}

/** Difficulty and tercile of every session, scored against the others in `sessions`. */
export function difficulty(sessions: Session[], repo: string, opts: GraphOptions = {}): DifficultyScore[] {
  const feats = sessions.map((s) => features(s, repo, opts));
  const scores = difficultyFromFeatures(feats);
  const rows = sessions.map((s, i) => ({ session_id: s.id, features: feats[i]!, difficulty: scores[i]! }));
  const t = terciles(rows);
  return rows.map((r) => ({ ...r, tercile: t.get(r.session_id)! }));
}
// Graph impact size for a session (DESIGN.md §"Difficulty and review"). Primary method: spawn
// `entire graph impact --symbol <s> --format json` for the symbols declared in the touched hunks of
// the session's commit, and sum caller and type-consumer counts. When entire is not installed or
// fails, fall back to the import fan-in of the touched files. The method used is always returned.

import { dirname, join, normalize } from "node:path";

export type ImpactMethod = "graph" | "fan-in";

export interface ImpactResult {
  size: number;
  method: ImpactMethod;
  /** Symbols queried with the graph; empty for fan-in. */
  symbols: string[];
}

export interface GraphOptions {
  /** Binary to spawn; default `entire` from PATH. */
  entireBin?: string;
  /** Per-call timeout in ms. */
  timeoutMs?: number;
  /** Max symbols queried per session. */
  maxSymbols?: number;
}

export const DEFAULT_TIMEOUT_MS = 30_000;
export const DEFAULT_MAX_SYMBOLS = 8;

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  return { ok: p.exitCode === 0, out: p.stdout.toString() };
}

const DECL =
  /^\s*(?:export\s+)?(?:default\s+)?(?:declare\s+)?(?:async\s+)?(?:abstract\s+)?(?:function\*?|class|interface|type|enum|const|let|var)\s+([A-Za-z_$][\w$]*)/;

/** Names declared on the added lines of `sha`'s diff, in diff order, deduplicated. */
export function symbolsInHunks(repo: string, sha: string): string[] {
  const r = git(repo, ["show", "--unified=0", "--format=", "--no-color", "--no-renames", sha]);
  if (!r.ok) return [];
  const seen = new Set<string>();
  for (const line of r.out.split("\n")) {
    if (!line.startsWith("+") || line.startsWith("+++")) continue;
    const m = DECL.exec(line.slice(1));
    if (m?.[1]) seen.add(m[1]);
  }
  return [...seen];
}

/** Callers plus type consumers in one `entire graph impact` JSON reply; null when it is not one. */
export function parseImpact(json: string): number | null {
  try {
    const j = JSON.parse(json) as {
      disambiguation_required?: boolean;
      focus?: unknown;
      callers?: { total?: number };
      type_consumers?: { total?: number };
    };
    if (!j || typeof j !== "object" || !j.focus) return null;
    return (j.callers?.total ?? 0) + (j.type_consumers?.total ?? 0);
  } catch {
    return null;
  }
}

/** One spawned impact query. `null` = the graph could not answer (missing binary, timeout, error). */
export function graphImpact(repo: string, symbol: string, opts: GraphOptions = {}): number | null {
  const bin = opts.entireBin ?? "entire";
  let p: ReturnType<typeof Bun.spawnSync>;
  try {
    p = Bun.spawnSync(
      [bin, "graph", "impact", "--repo", repo, "--symbol", symbol, "--format", "json", "--depth", "2"],
