1	// Tracks which lines a session's commit added and which later commits removed or replaced.
2	// DESIGN.md §"Score: reverted, rework". History is read along first parents only: a merge is
3	// diffed against its first parent, and the window walks first-parent commits after the landing.
4	
5	export const DEFAULT_WINDOW = 20;
6	export const EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";
7	const CHECKPOINT_TRAILER = /^Entire-Checkpoint:\s*\S+/m;
8	
9	/** A line is identified by its path and text. */
10	type LineKey = [path: string, text: string];
11	
12	export interface Tracked {
13	  /** Lines the commit added, against its first parent. */
14	  added: number;
15	  /** Added lines that a later commit in the window removed or replaced, by commits without a checkpoint trailer. */
16	  matchedHuman: number;
17	  /** The same, by commits with an Entire-Checkpoint trailer. */
18	  matchedAgent: number;
19	  /** Some later first-parent commit says `This reverts commit <sha>`. Not limited to the window. */
20	  explicitRevert: boolean;
21	}
22	
23	interface Commit {
24	  sha: string;
25	  parent: string;
26	  body: string;
27	}
28	
29	function git(repo: string, args: string[]): string {
30	  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
31	  if (p.exitCode !== 0) throw new Error(`git ${args.join(" ")} failed: ${p.stderr.toString().trim()}`);
32	  return p.stdout.toString();
33	}
34	
35	function fullSha(repo: string, ref: string): string {
36	  return git(repo, ["rev-parse", "--verify", `${ref}^{commit}`]).trim();
37	}
38	
39	/**
40	 * Commits after `sha` on the first-parent chain of HEAD, oldest first. Only descendants of `sha`
41	 * qualify, so a merge whose second parent carries `sha` is included. `--ancestry-path` is not
42	 * combined with `--first-parent`: that would drop the second-parent edge and miss the merge.
43	 */
44	function laterCommits(repo: string, sha: string): Commit[] {
45	  const descendants = new Set(git(repo, ["rev-list", "--ancestry-path", `${sha}..HEAD`]).split("\n"));
46	  const out = git(repo, ["log", "--first-parent", "--topo-order", "--reverse", "--format=%H %P%x1f%B%x1e", `${sha}..HEAD`]);
47	  return out
48	    .split("\x1e")
49	    .filter((rec) => rec.trim() !== "")
50	    .map((rec) => {
51	      const [head = "", body = ""] = rec.split("\x1f");
52	      const [commit = "", ...parents] = head.trim().split(" ");
53	      return { sha: commit, parent: parents[0] ?? EMPTY_TREE, body };
54	    })
55	    .filter((c) => descendants.has(c.sha));
56	}
57	
58	function parentOf(repo: string, sha: string): string {
59	  const parents = git(repo, ["log", "-1", "--format=%P", sha]).trim().split(" ");
60	  return parents[0] || EMPTY_TREE;
61	}
62	
63	/** Added and removed lines between two trees, read from hunk headers so that content like `--- x` is not mistaken for a header. */
64	function diffLines(repo: string, from: string, to: string): { added: LineKey[]; removed: LineKey[] } {
65	  const out = git(repo, ["diff", "-U0", "--no-color", "--no-ext-diff", "--no-renames", "--no-prefix", from, to]);
66	  const added: LineKey[] = [];
67	  const removed: LineKey[] = [];
68	  let oldPath = "";
69	  let path = "";
70	  let oldLeft = 0;
71	  let newLeft = 0;
72	  for (const line of out.split("\n")) {
73	    if (oldLeft > 0 && line.startsWith("-")) {
74	      removed.push([path, line.slice(1)]);
75	      oldLeft--;
76	    } else if (newLeft > 0 && line.startsWith("+")) {
77	      added.push([path, line.slice(1)]);
78	      newLeft--;
79	    } else if (line.startsWith("--- ")) {
80	      oldPath = line.slice(4).replace(/\t$/, "");
81	    } else if (line.startsWith("+++ ")) {
82	      const newPath = line.slice(4).replace(/\t$/, "");
83	      path = newPath === "/dev/null" ? oldPath : newPath;
84	    } else if (line.startsWith("@@ ")) {
85	      const m = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
86	      if (!m) throw new Error(`unparsable diff hunk: ${line}`);
87	      oldLeft = m[1] === undefined ? 1 : Number(m[1]);
88	      newLeft = m[2] === undefined ? 1 : Number(m[2]);
89	    }
90	  }
91	  return { added, removed };
92	}
93	
94	function bump(counts: Map<string, number>, key: string) {
95	  counts.set(key, (counts.get(key) ?? 0) + 1);
96	}
97	
98	/**
99	 * Follows the lines `sha` added through the next `window` first-parent commits. A removed or
100	 * replaced line counts once, for the first later commit that removes it. Lines are matched by
101	 * path and text as multisets, so a line that is re-added later is not counted as surviving.
102	 */
103	export function trackLines(repo: string, sha: string, window: number = DEFAULT_WINDOW): Tracked {
104	  const full = fullSha(repo, sha);
105	  const { added } = diffLines(repo, parentOf(repo, full), full);
106	  const later = laterCommits(repo, full);
107	  const alive = new Map<string, number>();
108	  for (const [path, text] of added) bump(alive, `${path}\0${text}`);
109	
110	  const result: Tracked = {
111	    added: added.length,
112	    matchedHuman: 0,
113	    matchedAgent: 0,
114	    explicitRevert: later.some((c) => c.body.includes(`This reverts commit ${full}`)),
115	  };
116	  if (added.length === 0) return result;
117	
118	  for (const c of later.slice(0, window)) {
119	    const agent = CHECKPOINT_TRAILER.test(c.body);
120	    for (const [path, text] of diffLines(repo, c.parent, c.sha).removed) {
121	      const key = `${path}\0${text}`;
122	      const n = alive.get(key) ?? 0;
123	      if (n === 0) continue;
124	      alive.set(key, n - 1);
125	      if (agent) result.matchedAgent++;
126	      else result.matchedHuman++;
127	    }
128	  }
129	  return result;
130	}
131	
132	export interface ReworkShares {
133	  /** Share of the commit's added lines that later commits without a checkpoint trailer modified. */
134	  human: number;
135	  /** Share of the commit's added lines that later commits with a checkpoint trailer modified. */
136	  agent: number;
137	}
138	
139	/** Shares of `sha`'s added lines that later first-parent commits in the window modified, split by author kind. */
140	export function rework(repo: string, sha: string, window: number = DEFAULT_WINDOW): ReworkShares {
141	  const t = trackLines(repo, sha, window);
142	  if (t.added === 0) return { human: 0, agent: 0 };
143	  return { human: t.matchedHuman / t.added, agent: t.matchedAgent / t.added };
144	}
145

