52	  try {
53	    const j = JSON.parse(json) as {
54	      disambiguation_required?: boolean;
55	      focus?: unknown;
56	      callers?: { total?: number };
57	      type_consumers?: { total?: number };
58	    };
59	    if (!j || typeof j !== "object" || !j.focus) return null;
60	    return (j.callers?.total ?? 0) + (j.type_consumers?.total ?? 0);
61	  } catch {
