71	    p = Bun.spawnSync(
72	      [bin, "graph", "impact", "--repo", repo, "--symbol", symbol, "--format", "json", "--depth", "2"],
73	      { cwd: repo, stdout: "pipe", stderr: "pipe", timeout: opts.timeoutMs ?? DEFAULT_TIMEOUT_MS },
74	    );
75	  } catch {
76	    return null;
77	  }
78	  if (p.exitCode !== 0 || !p.stdout) return null;
79	  return parseImpact(p.stdout.toString());
80	}
