82	// ---------- fallback: import fan-in ----------
83	
84	const IMPORT = /(?:\bfrom\s*|\bimport\s*\(?\s*|\brequire\s*\(\s*)["'](\.{1,2}\/[^"']+)["']/g;
85	const SOURCE = /\.(?:[cm]?[jt]sx?)$/;
86	const stripExt = (p: string) => p.replace(SOURCE, "").replace(/\/index$/, "");
87	
88	const fanInCache = new Map<string, Map<string, number>>();
89	
90	/** Module (path without extension) → number of distinct files at HEAD that import it relatively. */
91	export function importFanIn(repo: string): Map<string, number> {
92	  const head = git(repo, ["rev-parse", "HEAD"]).out.trim();
93	  const key = `${repo}@${head}`;
94	  const cached = fanInCache.get(key);
95	  if (cached) return cached;
96	  const counts = new Map<string, number>();
97	  const grep = git(repo, ["grep", "-I", "-E", "(from|import|require)", "HEAD", "--", "*.ts", "*.tsx", "*.js", "*.jsx", "*.mjs", "*.cjs", "*.mts", "*.cts"]);
98	  const importers = new Map<string, Set<string>>();
99	  for (const line of grep.out.split("\n")) {
100	    // `HEAD:path:content`
101	    const m = /^HEAD:([^:]+):(.*)$/.exec(line);
102	    if (!m) continue;
103	    const [, file, content] = m as unknown as [string, string, string];
104	    for (const im of content.matchAll(IMPORT)) {
105	      const target = stripExt(normalize(join(dirname(file), im[1]!)));
106	      if (target === stripExt(file)) continue;
107	      let set = importers.get(target);
108	      if (!set) importers.set(target, (set = new Set()));
109	      set.add(file);
110	    }
111	  }
112	  for (const [t, s] of importers) counts.set(t, s.size);
113	  fanInCache.set(key, counts);
114	  return counts;
115	}
116	
117	export function fanInSize(repo: string, files: string[]): number {
118	  const counts = importFanIn(repo);
119	  return files.reduce((sum, f) => sum + (counts.get(stripExt(normalize(f))) ?? 0), 0);
120	}
121	
122	// ---------- per session ----------
123	
124	/**
125	 * Impact size of a session's change. Graph when entire answers for every queried symbol; otherwise
126	 * fan-in over `files`. A session with no commit or no declared symbols uses fan-in.
127	 */
128	export function impactSize(repo: string, sha: string | null, files: string[], opts: GraphOptions = {}): ImpactResult {
129	  const symbols = sha ? symbolsInHunks(repo, sha).slice(0, opts.maxSymbols ?? DEFAULT_MAX_SYMBOLS) : [];
130	  if (symbols.length > 0) {
131	    let size = 0;
132	    let ok = true;
133	    for (const s of symbols) {
134	      const n = graphImpact(repo, s, opts);
135	      if (n === null) {
136	        ok = false;
137	        break;
138	      }
139	      size += n;
140	    }
141	    if (ok) return { size, method: "graph", symbols };
142	  }
143	  return { size: fanInSize(repo, files), method: "fan-in", symbols: [] };
144	}
